CREATE TABLE IF NOT EXISTS forgeos_migrations (id TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_memory_entries (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, author_type TEXT NOT NULL DEFAULT 'system', author_id TEXT, source TEXT NOT NULL, provenance_run_id UUID REFERENCES ai_runs(id) ON DELETE SET NULL, provenance_brain_version_id UUID REFERENCES project_brain_versions(id) ON DELETE SET NULL, supersedes_id UUID REFERENCES project_memory_entries(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'active', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_project_memory_project_time ON project_memory_entries(project_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_project_memory_kind ON project_memory_entries(project_id, kind);
CREATE TABLE IF NOT EXISTS conversations (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL DEFAULT 'ForgeOS Project Conversation', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_messages (id UUID PRIMARY KEY, conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, author_id TEXT, run_id UUID REFERENCES ai_runs(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_conversation_messages_time ON conversation_messages(conversation_id, created_at);
CREATE TABLE IF NOT EXISTS approval_requests (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, run_id UUID NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE, step_id UUID REFERENCES ai_run_steps(id) ON DELETE CASCADE, action_type TEXT NOT NULL, target TEXT NOT NULL, reason TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', actor_id TEXT, decision_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), decided_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_approval_requests_run ON approval_requests(run_id, status);
CREATE TABLE IF NOT EXISTS provider_attempts (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, run_id UUID REFERENCES ai_runs(id) ON DELETE SET NULL, kind TEXT NOT NULL, provider TEXT NOT NULL, capability TEXT NOT NULL, status TEXT NOT NULL, priority INTEGER, job_id TEXT, simulated BOOLEAN NOT NULL DEFAULT false, error TEXT, observations JSONB NOT NULL DEFAULT '{}'::jsonb, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_provider_attempts_run ON provider_attempts(run_id, started_at DESC);
CREATE TABLE IF NOT EXISTS environments (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', provider TEXT, config JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(project_id, name));
CREATE TABLE IF NOT EXISTS deployment_observations (id UUID PRIMARY KEY, deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE, status TEXT NOT NULL, url TEXT, provider_job_id TEXT, simulated BOOLEAN NOT NULL DEFAULT false, detail JSONB NOT NULL DEFAULT '{}'::jsonb, observed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_deployment_observations_time ON deployment_observations(deployment_id, observed_at DESC);
ALTER TABLE source_snapshots ADD COLUMN IF NOT EXISTS parent_snapshot_id UUID REFERENCES source_snapshots(id) ON DELETE SET NULL;
ALTER TABLE source_snapshots ADD COLUMN IF NOT EXISTS provider TEXT;
ALTER TABLE source_snapshots ADD COLUMN IF NOT EXISTS verified BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE test_runs ADD COLUMN IF NOT EXISTS simulated BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE deployments ADD COLUMN IF NOT EXISTS simulated BOOLEAN NOT NULL DEFAULT false;